mapper.select:
select count(*)
from notifications
where receiver_user_id = #{receiverUserId}
  and dedupe_key = #{dedupeKey}

mapper.insert:
insert into notifications (
    id, receiver_user_id, actor_user_id, type, content_id, comment_id,
    message, event_id, dedupe_key, payload_json
)
values (
    #{id}, #{receiverUserId}, #{actorUserId}, #{type}, #{contentId}, #{commentId},
    #{message}, #{eventId}, #{dedupeKey}, #{payloadJson}
)

insert into notification_deliveries (id, notification_id, device_token_id)
select #{deliveryId}, #{notificationId}, #{deviceId}
where not exists (
    select 1
    from notification_deliveries
    where notification_id = #{notificationId}
      and device_token_id = #{deviceId}
)
